package mod.cdv.tnpc.tactical;
import java.util.*;
/** Plans a bounded number of real crafting recipes using only owned ingredients. */
public final class CraftPlanner {
 static Object c(Object o,String n,Object...a){return Social.c(o,n,a);}
 public static boolean table(Object n){Object w=Social.world(n);int x=(int)Math.floor(Social.num(c(n,"getX"))),y=(int)Math.floor(Social.num(c(n,"getY"))),z=(int)Math.floor(Social.num(c(n,"getZ")));for(int dx=-3;dx<=3;dx++)for(int dz=-3;dz<=3;dz++)for(int dy=-1;dy<=1;dy++){Object p=Tasks.pos(x+dx,y+dy,z+dz);if(Social.yes(c(w,"hasChunkAt",p))&&Tasks.block(w,p).equals("minecraft:crafting_table")&&Tasks.permitted(n,p))return true;}return false;}
 static boolean need(Object n,List<Object> bag,Object output)throws Exception{if(CalmLoot.empty(output)||!Tasks.useful(output))return false;String id=CalmLoot.id(output);int count=0;for(Object s:bag)if(CalmLoot.id(s).equals(id))count+=((Number)c(s,"getCount")).intValue();for(String slot:CalmLoot.SLOTS)if(CalmLoot.id(c(n,"getItemBySlot",CalmLoot.slot(slot))).equals(id))count++;if(CalmLoot.id(c(n,"getMainHandItem")).equals(id))count++;int wanted=id.contains("ammo")?32:id.contains("bandage")||id.contains("plaster")?8:id.endsWith("_planks")||id.contains("stick")||id.contains("torch")?16:id.contains("bread")||id.contains("beef")?8:1;return count<wanted;}
 public static boolean craft(Object n)throws Exception{Object w=Social.world(n),manager=c(w,"getRecipeManager"),type=SocialR.get(Social.t("net.minecraft.world.item.crafting.RecipeType"),"CRAFTING");List<?> recipes=(List<?>)c(manager,"getAllRecipesFor",type);if(recipes.isEmpty())return false;List<Object> bag=CalmLoot.bag(n);if(bag.size()>=40)return false;Social.Memory memory=Social.mem(n);
  for(int examined=0;examined<Math.min(24,recipes.size());examined++){Object value=c(recipes.get(Math.floorMod(memory.craftIndex++,recipes.size())),"value"),output=c(value,"getResultItem",c(w,"registryAccess"));if(!need(n,bag,output))continue;List<?> ingredients=(List<?>)c(value,"getIngredients");if(ingredients.isEmpty()||ingredients.size()>9)continue;int width=3,height=3;boolean shaped=Social.t("net.minecraft.world.item.crafting.ShapedRecipe").isInstance(value);if(shaped){width=((Number)c(value,"getWidth")).intValue();height=((Number)c(value,"getHeight")).intValue();}else{width=Math.min(ingredients.size(),3);height=(ingredients.size()+2)/3;}if(width>3||height>3)continue;if((shaped&&(width>2||height>2)||!shaped&&ingredients.size()>4)&&!table(n))continue;
   List<Object> grid=new ArrayList<>(Collections.nCopies(9,CalmLoot.emptyStack()));Map<Object,Integer> used=new IdentityHashMap<>();boolean ready=true;for(int j=0;j<ingredients.size();j++){Object ingredient=ingredients.get(j);if(Social.yes(c(ingredient,"isEmpty")))continue;Object picked=null;for(Object s:bag)if(((Number)c(s,"getCount")).intValue()>used.getOrDefault(s,0)&&Social.yes(c(ingredient,"test",s))){picked=s;break;}if(picked==null){ready=false;break;}used.merge(picked,1,Integer::sum);int position=shaped?(j/width)*3+j%width:ingredients.size()<=4?(j/2)*3+j%2:j;grid.set(position,c(picked,"copyWithCount",1));}if(!ready)continue;Object input=c(Social.t("net.minecraft.world.item.crafting.CraftingInput"),"of",3,3,grid);Optional<?> verified=(Optional<?>)c(manager,"getRecipeFor",type,input,w);if(verified.isEmpty())continue;Object actual=c(verified.get(),"value"),result=c(actual,"assemble",input,c(w,"registryAccess"));if(!need(n,bag,result))continue;
   List<Object> remaining=new ArrayList<>();for(Object s:(Iterable<?>)c(actual,"getRemainingItems",input))if(!CalmLoot.empty(s))remaining.add(c(s,"copy"));if(bag.size()+remaining.size()+1>47)continue;for(var entry:used.entrySet())c(entry.getKey(),"shrink",entry.getValue());bag.removeIf(s->Social.yes(c(s,"isEmpty")));Tasks.put(bag,result);for(Object s:remaining)Tasks.put(bag,s);CalmLoot.saveBag(n,bag);return true;
  }return false;
 }
}
